    private final BoolSetting placeSwapBack = new BoolSetting(new EncryptedString(new char[]{0x82da, 0x76bf, 0x0b0f, 0xeba3, 0x9633, 0xa8a7, 0x37db, 0x1c93, 0xfce4, 0xbc0a, 0xb12f, 0xd12a, 0x6557, 0x2279, 0x11b0}, new char[]{0xd17a, 0xa8cb, 0x2218, 0xbc69, 0x37be, 0xb10f, 0x0b5c, 0x82ad, 0x1cf2, 0x9643, 0x1190, 0xebe1, 0x6536, 0xfc87, 0x76d4}), true);
